const trackerSites = `-- name: TrackerSites :many

SELECT t.id, t.workspace_id, t.name, t.origin, t.store_id, t.wait_consent, t.identify_secret_sealed, t.created_by, t.created_at, t.updated_at, t.last_event_at, t.deleted_at, coalesce(st.name, '')::text AS store_name, coalesce(st.platform, '')::text AS store_platform,
       coalesce(st.status, '')::text AS store_status, coalesce(u.name, '')::text AS created_by_name
FROM tracker_sites t
LEFT JOIN stores st ON st.id = t.store_id
LEFT JOIN users u ON u.id = t.created_by
WHERE t.workspace_id = $1 AND t.deleted_at IS NULL
ORDER BY t.created_at, t.id
`

type TrackerSitesRow struct {
	ID                   uuid.UUID  `json:"id"`
	WorkspaceID          uuid.UUID  `json:"workspaceId"`
	Name                 string     `json:"name"`
	Origin               string     `json:"origin"`
	StoreID              *uuid.UUID `json:"storeId"`
	WaitConsent          bool       `json:"waitConsent"`
	IdentifySecretSealed []byte     `json:"identifySecretSealed"`
	CreatedBy            *uuid.UUID `json:"createdBy"`
	CreatedAt            time.Time  `json:"createdAt"`
	UpdatedAt            time.Time  `json:"updatedAt"`
	LastEventAt          *time.Time `json:"lastEventAt"`
	DeletedAt            *time.Time `json:"deletedAt"`
	StoreName            string     `json:"storeName"`
	StorePlatform        string     `json:"storePlatform"`
	StoreStatus          string     `json:"storeStatus"`
	CreatedByName        string     `json:"createdByName"`
}

// The site tracker (M62 G-28): sites, the collect writer's batches,
// identification, the contact timeline, the hub card and retention.
// A workspace's sites, newest last, with the store each is linked to.
func (q *Queries) TrackerSites(ctx context.Context, workspaceID uuid.UUID) ([]TrackerSitesRow, error) {
	rows, err := q.db.Query(ctx, trackerSites, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TrackerSitesRow{}
	for rows.Next() {
		var i TrackerSitesRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.Origin,
			&i.StoreID,
			&i.WaitConsent,
			&i.IdentifySecretSealed,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastEventAt,
			&i.DeletedAt,
			&i.StoreName,
			&i.StorePlatform,
			&i.StoreStatus,
			&i.CreatedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trackerSitesTouch = `-- name: TrackerSitesTouch :exec
UPDATE tracker_sites s SET last_event_at = x.at
FROM (SELECT unnest($1::uuid[]) AS id, unnest($2::timestamptz[]) AS at) x
WHERE s.id = x.id AND (s.last_event_at IS NULL OR s.last_event_at < x.at)
`

type TrackerSitesTouchParams struct {
	Ids []uuid.UUID `json:"ids"`
	At  []time.Time `json:"at"`
}

// The last event of each site of a batch.
func (q *Queries) TrackerSitesTouch(ctx context.Context, arg TrackerSitesTouchParams) error {
	_, err := q.db.Exec(ctx, trackerSitesTouch, arg.Ids, arg.At)
	return err
}

