const trackerStockRequestsAdd = `-- name: TrackerStockRequestsAdd :exec
INSERT INTO store_stock_requests (workspace_id, contact_id, product_id, created_at)
SELECT unnest($1::uuid[]), unnest($2::uuid[]), unnest($3::uuid[]), unnest($4::timestamptz[])
ON CONFLICT (contact_id, product_id) DO UPDATE SET created_at = EXCLUDED.created_at, notified_at = NULL
`

type TrackerStockRequestsAddParams struct {
	WorkspaceIds []uuid.UUID `json:"workspaceIds"`
	ContactIds   []uuid.UUID `json:"contactIds"`
	ProductIds   []uuid.UUID `json:"productIds"`
	At           []time.Time `json:"at"`
}

// "Email me when it's back" from known visitors: asking again starts over.
func (q *Queries) TrackerStockRequestsAdd(ctx context.Context, arg TrackerStockRequestsAddParams) error {
	_, err := q.db.Exec(ctx, trackerStockRequestsAdd,
		arg.WorkspaceIds,
		arg.ContactIds,
		arg.ProductIds,
		arg.At,
	)
	return err
}

