const trackerVisitorProductsAdd = `-- name: TrackerVisitorProductsAdd :exec
INSERT INTO tracker_visitor_products AS v (visitor_id, product_id, views, carts, last_viewed_at, last_carted_at)
SELECT unnest($1::uuid[]), unnest($2::uuid[]), unnest($3::int[]), unnest($4::int[]),
       nullif(unnest($5::timestamptz[]), 'epoch'), nullif(unnest($6::timestamptz[]), 'epoch')
ON CONFLICT (visitor_id, product_id) DO UPDATE SET views = v.views + EXCLUDED.views, carts = v.carts + EXCLUDED.carts,
    last_viewed_at = greatest(v.last_viewed_at, EXCLUDED.last_viewed_at), last_carted_at = greatest(v.last_carted_at, EXCLUDED.last_carted_at)
`

type TrackerVisitorProductsAddParams struct {
	VisitorIds []uuid.UUID `json:"visitorIds"`
	ProductIds []uuid.UUID `json:"productIds"`
	Views      []int32     `json:"views"`
	Carts      []int32     `json:"carts"`
	Viewed     []time.Time `json:"viewed"`
	Carted     []time.Time `json:"carted"`
}

// The same for visitors not linked to a contact yet.
func (q *Queries) TrackerVisitorProductsAdd(ctx context.Context, arg TrackerVisitorProductsAddParams) error {
	_, err := q.db.Exec(ctx, trackerVisitorProductsAdd,
		arg.VisitorIds,
		arg.ProductIds,
		arg.Views,
		arg.Carts,
		arg.Viewed,
		arg.Carted,
	)
	return err
}

const trackerVisitorsUpsert = `-- name: TrackerVisitorsUpsert :many
INSERT INTO tracker_visitors (id, workspace_id, vid_hash, first_seen, last_seen)
SELECT unnest($1::uuid[]), unnest($2::uuid[]), unnest($3::bytea[]), unnest($4::timestamptz[]), unnest($4::timestamptz[])
ON CONFLICT (workspace_id, vid_hash) DO UPDATE SET last_seen = greatest(tracker_visitors.last_seen, EXCLUDED.last_seen)
RETURNING id, workspace_id, vid_hash, contact_id
`

type TrackerVisitorsUpsertParams struct {
	Ids          []uuid.UUID `json:"ids"`
	WorkspaceIds []uuid.UUID `json:"workspaceIds"`
	Hashes       [][]byte    `json:"hashes"`
	Seen         []time.Time `json:"seen"`
}

type TrackerVisitorsUpsertRow struct {
	ID          uuid.UUID  `json:"id"`
	WorkspaceID uuid.UUID  `json:"workspaceId"`
	VidHash     []byte     `json:"vidHash"`
	ContactID   *uuid.UUID `json:"contactId"`
}

// A batch's visitors, in (workspace, hash) order: new ones are added, the
// others seen again; each comes back with the contact it is linked to.
func (q *Queries) TrackerVisitorsUpsert(ctx context.Context, arg TrackerVisitorsUpsertParams) ([]TrackerVisitorsUpsertRow, error) {
	rows, err := q.db.Query(ctx, trackerVisitorsUpsert,
		arg.Ids,
		arg.WorkspaceIds,
		arg.Hashes,
		arg.Seen,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TrackerVisitorsUpsertRow{}
	for rows.Next() {
		var i TrackerVisitorsUpsertRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.VidHash,
			&i.ContactID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
